import sys

M = 10**9 + 7

def fib(n):
    # returns (F(n), F(n+1)) modulo M by fast doubling
    if n == 0:
        return (0, 1)
    a, b = fib(n >> 1)
    c = a * ((2 * b - a) % M) % M
    d = (a * a + b * b) % M
    if n & 1:
        return (d, (c + d) % M)
    return (c, d)

def main():
    n = int(sys.stdin.read().split()[0])
    # count(n) = F(n + 2)
    print(fib(n + 1)[1])

main()

